+
+function invalidCursor(message = 'Invalid or stale cursor') {
+  const err = new Error(message);
+  err.code = 'INVALID_CURSOR';
+  return err;
+}
+
+function encodeCursor(offset, sig) {
+  return Buffer.from(JSON.stringify({ offset, sig }), 'utf8').toString('base64url');
+}
+
+function decodeCursor(cursor, sig) {
+  if (typeof cursor !== 'string' || cursor.length === 0) throw invalidCursor();
+  let obj;
+  try {
+    obj = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
+  } catch {
+    throw invalidCursor();
+  }
+  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) throw invalidCursor();
+  if (!Number.isInteger(obj.offset) || obj.offset < 0) throw invalidCursor();
+  if (typeof obj.sig !== 'string' || obj.sig !== sig) throw invalidCursor();
+  return obj.offset;
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'page',
+      description:
+        'Page over rows.json. Returns a page of rows and a next_cursor when more rows remain. Cursors are opaque tokens; an invalid or stale cursor throws INVALID_CURSOR.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          limit: {
+            type: 'integer',
+            minimum: 1,
+            maximum: 2,
+            description: 'Number of rows to return per page (1-2, inclusive).'
+          },
+          cursor: {
+            type: 'string',
+            description: 'Opaque cursor returned by a previous page call. Optional for the first page.'
+          }
+        },
+        required: ['limit'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'page') {
+    throw new Error(`Tool not found: ${name}`);
+  }
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Invalid arguments: expected an object');
+  }
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_ARGS.has(key)) {
+      throw new Error(`Invalid argument: ${key}`);
+    }
+  }
+  if (!('limit' in args)) {
+    throw new Error('Missing required argument: limit');
+  }
+  const limit = args.limit;
+  if (!Number.isInteger(limit)) {
+    throw new Error('Invalid argument: limit must be an integer');
+  }
+  if (limit < 1 || limit > 2) {
+    throw new Error('Invalid argument: limit must be between 1 and 2');
+  }
+
+  const { rows, sig } = loadRows();
+
+  let offset = 0;
+  if ('cursor' in args) {
+    if (typeof args.cursor !== 'string') {
+      throw new Error('Invalid argument: cursor must be a string');
+    }
+    offset = decodeCursor(args.cursor, sig); // throws INVALID_CURSOR on bad/stale cursor
+  }
+
+  if (offset > rows.length) {
+    throw invalidCursor();
+  }
+
+  const slice = rows.slice(offset, offset + limit);
+  const next = offset + limit < rows.length ? encodeCursor(offset + limit, sig) : null;
+  return { rows: slice, next_cursor: next };
+}
